//! Accepts connections and serves one request per connection, each on its
//! own concurrent task.

const std = @import("std");
const Io = std.Io;
const net = Io.net;
const Allocator = std.mem.Allocator;

const Store = @import("Store.zig");
const http = @import("http.zig");
const router = @import("router.zig");

const Server = @This();

const log = std.log.scoped(.kvhttp);

pub const max_value_len = 1 << 20;

/// Must hold the entire request head.
const recv_buffer_len = 16 * 1024;
const send_buffer_len = 16 * 1024;
/// After responding early (e.g. 413), at most this many unread request-body
/// bytes are discarded so that closing the socket does not reset the
/// connection before the client has read the response.
const max_drain_len = 4 * max_value_len;

io: Io,
gpa: Allocator,
store: *Store,

/// Accepts connections until canceled.
pub fn run(server: *Server, listener: *net.Server) Io.Cancelable!void {
    const io = server.io;
    var group: Io.Group = .init;
    defer group.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.Canceled => return error.Canceled,
            error.ConnectionAborted => continue,
            else => {
                log.warn("accept failed: {t}", .{err});
                // Typically descriptor exhaustion; back off instead of spinning.
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
        };
        group.concurrent(io, serveConnection, .{ server, stream }) catch {
            // No spare concurrency: serve inline rather than drop the client.
            server.serveConnection(stream);
        };
    }
}

fn serveConnection(server: *Server, stream: net.Stream) void {
    const io = server.io;
    defer stream.close(io);

    var recv_buffer: [recv_buffer_len]u8 = undefined;
    var send_buffer: [send_buffer_len]u8 = undefined;
    var stream_reader = stream.reader(io, &recv_buffer);
    var stream_writer = stream.writer(io, &send_buffer);
    const r = &stream_reader.interface;

    var unread_body: u64 = 0;
    server.handleRequest(r, &stream_writer.interface, &unread_body) catch |err| switch (err) {
        // The peer went away or the socket failed; nothing more can be sent.
        error.ReadFailed, error.WriteFailed, error.EndOfStream, error.Canceled => return,
    };

    if (unread_body > 0) {
        stream.shutdown(io, .send) catch return;
        r.discardAll64(@min(unread_body, max_drain_len)) catch {};
    }
}

const HandleError = Io.Reader.Error || Io.Writer.Error || Io.Cancelable;

/// Reads one request from `r` and writes the response to `w`. On return,
/// `unread_body` holds the number of declared request-body bytes not consumed.
fn handleRequest(server: *Server, r: *Io.Reader, w: *Io.Writer, unread_body: *u64) HandleError!void {
    const head_bytes = http.receiveHead(r) catch |err| switch (err) {
        error.HeadTooLarge => return http.writeResponse(w, .{ .status = .request_header_fields_too_large }),
        else => |e| return e,
    };
    const head = http.Head.parse(head_bytes) catch |err| return http.writeResponse(w, .{ .status = switch (err) {
        error.BadRequest => .bad_request,
        error.VersionNotSupported => .http_version_not_supported,
        error.ExpectationFailed => .expectation_failed,
    } });
    unread_body.* = head.content_length orelse 0;

    var body_buffer: ?[]u8 = null;
    defer if (body_buffer) |buffer| server.gpa.free(buffer);

    const response = server.respond(r, w, head, unread_body, &body_buffer) catch |err| switch (err) {
        error.OutOfMemory => blk: {
            log.err("out of memory serving {s} {s}", .{ head.method, head.target });
            break :blk http.Response{ .status = .internal_server_error };
        },
        else => |e| return e,
    };
    try http.writeResponse(w, response);
}

/// Executes the routed request. Response bodies that need freeing are
/// returned through `body_buffer`, allocated with `gpa`.
fn respond(
    server: *Server,
    r: *Io.Reader,
    w: *Io.Writer,
    head: http.Head,
    unread_body: *u64,
    body_buffer: *?[]u8,
) (HandleError || Allocator.Error)!http.Response {
    const io = server.io;
    const store = server.store;

    switch (router.resolve(head.method, head.target)) {
        .health => return .{ .status = .ok, .content_type = "text/plain; charset=utf-8", .body = "ok" },
        .list_keys => {
            const json = try store.keysJson(io, server.gpa);
            body_buffer.* = json;
            return .{ .status = .ok, .content_type = "application/json", .body = json };
        },
        .get => |key| {
            const value = try store.get(io, server.gpa, key) orelse return .{ .status = .not_found };
            body_buffer.* = value;
            return .{ .status = .ok, .content_type = "application/octet-stream", .body = value };
        },
        .delete => |key| return .{ .status = if (try store.delete(io, key)) .no_content else .not_found },
        .put => |key_in_head| {
            if (head.has_transfer_encoding) return .{ .status = .length_required };
            const len = head.content_length orelse 0;
            if (len > max_value_len) return .{ .status = .payload_too_large };

            // `key_in_head` points into the reader's buffer, which reading the body may overwrite.
            var key_storage: [router.max_key_len]u8 = undefined;
            const key = key_storage[0..key_in_head.len];
            @memcpy(key, key_in_head);

            if (head.expect_continue) try http.writeContinue(w);

            const value = try server.gpa.alloc(u8, @intCast(len));
            errdefer server.gpa.free(value);
            try r.readSliceAll(value);
            unread_body.* = 0;

            return .{ .status = switch (try store.put(io, key, value)) {
                .created => .created,
                .replaced => .ok,
            } };
        },
        .status => |status| return .{ .status = status },
    }
}

//! Thread-safe in-memory key-value store.
//!
//! Keys and values are owned by the store and allocated with `gpa`. Readers
//! receive copies so the lock is never held while data is being sent to a
//! (possibly slow) client.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

const Store = @This();

gpa: Allocator,
lock: Io.RwLock = .init,
entries: std.StringHashMapUnmanaged([]u8) = .empty,

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(store: *Store) void {
    var it = store.entries.iterator();
    while (it.next()) |entry| {
        store.gpa.free(entry.key_ptr.*);
        store.gpa.free(entry.value_ptr.*);
    }
    store.entries.deinit(store.gpa);
    store.* = undefined;
}

pub const PutResult = enum { created, replaced };

/// Stores `value` under `key`, replacing any previous value.
///
/// `value` must be allocated with the store's `gpa`; on success the store
/// takes ownership of it. On error the caller still owns it.
pub fn put(store: *Store, io: Io, key: []const u8, value: []u8) (Allocator.Error || Io.Cancelable)!PutResult {
    try store.lock.lock(io);
    defer store.lock.unlock(io);

    const gop = try store.entries.getOrPut(store.gpa, key);
    if (gop.found_existing) {
        store.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = value;
        return .replaced;
    }
    gop.key_ptr.* = store.gpa.dupe(u8, key) catch |err| {
        store.entries.removeByPtr(gop.key_ptr);
        return err;
    };
    gop.value_ptr.* = value;
    return .created;
}

/// Returns a copy of the value stored under `key`, owned by the caller and
/// allocated with `allocator`, or `null` if the key is absent.
pub fn get(store: *Store, io: Io, allocator: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try store.lock.lockShared(io);
    defer store.lock.unlockShared(io);

    const value = store.entries.get(key) orelse return null;
    return try allocator.dupe(u8, value);
}

/// Removes `key`. Returns whether it was present.
pub fn delete(store: *Store, io: Io, key: []const u8) Io.Cancelable!bool {
    try store.lock.lock(io);
    defer store.lock.unlock(io);

    const kv = store.entries.fetchRemove(key) orelse return false;
    store.gpa.free(kv.key);
    store.gpa.free(kv.value);
    return true;
}

/// Renders every key, sorted ascending, as a JSON array of strings.
/// The result is owned by the caller and allocated with `allocator`.
///
/// Keys are restricted to `[A-Za-z0-9_-]`, so no JSON escaping is required.
pub fn keysJson(store: *Store, io: Io, allocator: Allocator) (Allocator.Error || Io.Cancelable)![]u8 {
    var keys: std.ArrayList([]const u8) = .empty;
    defer keys.deinit(allocator);

    var json: std.ArrayList(u8) = .empty;
    errdefer json.deinit(allocator);

    {
        try store.lock.lockShared(io);
        defer store.lock.unlockShared(io);

        try keys.ensureTotalCapacityPrecise(allocator, store.entries.count());
        var len: usize = 2; // "[" and "]"
        var it = store.entries.keyIterator();
        while (it.next()) |key| {
            keys.appendAssumeCapacity(key.*);
            len += key.len + 3; // quotes and comma
        }
        std.mem.sortUnstable([]const u8, keys.items, {}, lessThan);

        // Rendered while still holding the lock: the key slices are owned by the map.
        try json.ensureTotalCapacityPrecise(allocator, len);
        json.appendAssumeCapacity('[');
        for (keys.items, 0..) |key, i| {
            if (i != 0) json.appendAssumeCapacity(',');
            json.appendAssumeCapacity('"');
            json.appendSliceAssumeCapacity(key);
            json.appendAssumeCapacity('"');
        }
        json.appendAssumeCapacity(']');
    }

    return json.toOwnedSlice(allocator);
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

const testing = std.testing;

fn putCopy(store: *Store, key: []const u8, value: []const u8) !PutResult {
    const owned = try store.gpa.dupe(u8, value);
    errdefer store.gpa.free(owned);
    return store.put(testing.io, key, owned);
}

test "put, get, replace, delete" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    try testing.expectEqual(.created, try putCopy(&store, "a", "hello"));
    {
        const value = (try store.get(io, testing.allocator, "a")).?;
        defer testing.allocator.free(value);
        try testing.expectEqualStrings("hello", value);
    }
    try testing.expectEqual(.replaced, try putCopy(&store, "a", "world"));
    {
        const value = (try store.get(io, testing.allocator, "a")).?;
        defer testing.allocator.free(value);
        try testing.expectEqualStrings("world", value);
    }
    try testing.expect(try store.delete(io, "a"));
    try testing.expect(!try store.delete(io, "a"));
    try testing.expectEqual(null, try store.get(io, testing.allocator, "a"));
}

test "empty values are stored" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    try testing.expectEqual(.created, try putCopy(&store, "k", ""));
    const value = (try store.get(io, testing.allocator, "k")).?;
    defer testing.allocator.free(value);
    try testing.expectEqual(0, value.len);
}

test "keysJson sorts ascending" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    {
        const json = try store.keysJson(io, testing.allocator);
        defer testing.allocator.free(json);
        try testing.expectEqualStrings("[]", json);
    }
    for ([_][]const u8{ "b", "a", "_", "Z", "c-1", "c" }) |key| _ = try putCopy(&store, key, "v");
    const json = try store.keysJson(io, testing.allocator);
    defer testing.allocator.free(json);
    try testing.expectEqualStrings("[\"Z\",\"_\",\"a\",\"b\",\"c\",\"c-1\"]", json);
}

//! Minimal HTTP/1.1 request-head parsing and response serialization.
//!
//! `std.http.Server` only accepts the methods in `std.http.Method`; this
//! server must answer arbitrary method tokens with `405`, so it parses the
//! request head itself.

const std = @import("std");
const Io = std.Io;
const Status = std.http.Status;

pub const Head = struct {
    method: []const u8,
    target: []const u8,
    content_length: ?u64 = null,
    expect_continue: bool = false,
    /// A `Transfer-Encoding` header was present. Only `Content-Length`
    /// framing is supported.
    has_transfer_encoding: bool = false,

    pub const ParseError = error{
        /// The request line or a header line is malformed.
        BadRequest,
        /// The HTTP version is not 1.x.
        VersionNotSupported,
        /// The `Expect` header has a value other than `100-continue`.
        ExpectationFailed,
    };

    /// Parses a complete request head (as returned by `receiveHead`).
    /// Slices in the result point into `bytes`.
    pub fn parse(bytes: []const u8) ParseError!Head {
        var lines = std.mem.splitScalar(u8, bytes, '\n');

        const request_line = trimCr(lines.first());
        var parts = std.mem.splitScalar(u8, request_line, ' ');
        const method = parts.next() orelse return error.BadRequest;
        const target = parts.next() orelse return error.BadRequest;
        const version = parts.next() orelse return error.BadRequest;
        if (parts.next() != null) return error.BadRequest;
        if (method.len == 0 or !isToken(method)) return error.BadRequest;
        if (target.len == 0) return error.BadRequest;
        if (!std.mem.startsWith(u8, version, "HTTP/")) return error.BadRequest;
        if (!std.mem.startsWith(u8, version, "HTTP/1.")) return error.VersionNotSupported;

        var head: Head = .{ .method = method, .target = target };
        while (lines.next()) |raw_line| {
            const line = trimCr(raw_line);
            if (line.len == 0) break;
            if (line[0] == ' ' or line[0] == '\t') return error.BadRequest; // obsolete line folding

            const colon = std.mem.findScalar(u8, line, ':') orelse return error.BadRequest;
            const name = line[0..colon];
            const value = std.mem.trim(u8, line[colon + 1 ..], " \t");
            if (name.len == 0 or !isToken(name)) return error.BadRequest;

            if (std.ascii.eqlIgnoreCase(name, "content-length")) {
                const length = parseContentLength(value) orelse return error.BadRequest;
                if (head.content_length) |previous| {
                    if (previous != length) return error.BadRequest;
                }
                head.content_length = length;
            } else if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) {
                head.has_transfer_encoding = true;
            } else if (std.ascii.eqlIgnoreCase(name, "expect")) {
                if (!std.ascii.eqlIgnoreCase(value, "100-continue")) return error.ExpectationFailed;
                head.expect_continue = true;
            }
        }
        return head;
    }

    fn trimCr(line: []const u8) []const u8 {
        return std.mem.trimEnd(u8, line, "\r");
    }

    fn parseContentLength(value: []const u8) ?u64 {
        if (value.len == 0) return null;
        for (value) |c| if (!std.ascii.isDigit(c)) return null;
        return std.fmt.parseInt(u64, value, 10) catch null;
    }

    /// RFC 9110 `token`.
    fn isToken(s: []const u8) bool {
        for (s) |c| switch (c) {
            'A'...'Z', 'a'...'z', '0'...'9' => {},
            '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~' => {},
            else => return false,
        };
        return true;
    }
};

pub const ReceiveHeadError = error{
    /// The head does not fit in the reader's buffer.
    HeadTooLarge,
} || Io.Reader.Error;

/// Reads from `r` until a complete request head has been buffered, then
/// consumes it and returns its bytes. The returned slice is valid until the
/// next read from `r`.
pub fn receiveHead(r: *Io.Reader) ReceiveHeadError![]const u8 {
    var parser: std.http.HeadParser = .{};
    var scanned: usize = 0;
    while (true) {
        const buffered = r.buffered();
        scanned += parser.feed(buffered[scanned..]);
        if (parser.state == .finished) {
            r.toss(scanned);
            return buffered[0..scanned];
        }
        if (buffered.len == r.buffer.len) return error.HeadTooLarge;
        try r.fillMore();
    }
}

pub const Response = struct {
    status: Status,
    content_type: ?[]const u8 = null,
    body: []const u8 = "",
};

/// Serializes a complete response. Every response closes the connection.
pub fn writeResponse(w: *Io.Writer, response: Response) Io.Writer.Error!void {
    try w.print("HTTP/1.1 {d} {s}\r\n", .{
        @intFromEnum(response.status), response.status.phrase() orelse "",
    });
    if (response.content_type) |content_type| {
        try w.print("Content-Type: {s}\r\n", .{content_type});
    }
    // A 204 response must not carry a body or a Content-Length (RFC 9110 §8.6).
    if (response.status != .no_content) {
        try w.print("Content-Length: {d}\r\n", .{response.body.len});
    }
    try w.writeAll("Connection: close\r\n\r\n");
    if (response.status != .no_content) try w.writeAll(response.body);
    try w.flush();
}

pub fn writeContinue(w: *Io.Writer) Io.Writer.Error!void {
    try w.writeAll("HTTP/1.1 100 Continue\r\n\r\n");
    try w.flush();
}

const testing = std.testing;

test "parse request head" {
    const head = try Head.parse("PUT /kv/a HTTP/1.1\r\nHost: x\r\ncontent-length: 5\r\nConnection: close\r\n\r\n");
    try testing.expectEqualStrings("PUT", head.method);
    try testing.expectEqualStrings("/kv/a", head.target);
    try testing.expectEqual(5, head.content_length);
    try testing.expect(!head.has_transfer_encoding);
    try testing.expect(!head.expect_continue);
}

test "parse accepts arbitrary method tokens and bare LF" {
    const head = try Head.parse("FROB /health HTTP/1.0\nExpect: 100-continue\n\n");
    try testing.expectEqualStrings("FROB", head.method);
    try testing.expectEqual(null, head.content_length);
    try testing.expect(head.expect_continue);
}

test "parse rejects malformed heads" {
    try testing.expectError(error.BadRequest, Head.parse("GET /\r\n\r\n"));
    try testing.expectError(error.BadRequest, Head.parse("GET / HTTP/1.1 x\r\n\r\n"));
    try testing.expectError(error.BadRequest, Head.parse("GET / HTTP/1.1\r\nno-colon\r\n\r\n"));
    try testing.expectError(error.BadRequest, Head.parse("GET / HTTP/1.1\r\nContent-Length: -1\r\n\r\n"));
    try testing.expectError(error.BadRequest, Head.parse("GET / HTTP/1.1\r\nContent-Length: 1\r\nContent-Length: 2\r\n\r\n"));
    try testing.expectError(error.VersionNotSupported, Head.parse("GET / HTTP/2.0\r\n\r\n"));
    try testing.expectError(error.ExpectationFailed, Head.parse("GET / HTTP/1.1\r\nExpect: nope\r\n\r\n"));
}

test "receiveHead leaves the body buffered" {
    var r: Io.Reader = .fixed("PUT /kv/a HTTP/1.1\r\nContent-Length: 3\r\n\r\nabc");
    const bytes = try receiveHead(&r);
    try testing.expectEqualStrings("PUT /kv/a HTTP/1.1\r\nContent-Length: 3\r\n\r\n", bytes);
    try testing.expectEqualStrings("abc", r.buffered());
}

test "receiveHead reports truncated and oversized heads" {
    var buffer: [64]u8 = undefined;
    {
        var source: Io.Reader = .fixed("GET / HTTP/1.1\r\n");
        var limited = source.limited(.unlimited, &buffer);
        try testing.expectError(error.EndOfStream, receiveHead(&limited.interface));
    }
    {
        var source: Io.Reader = .fixed("GET / HTTP/1.1\r\nX-Long: " ++ "x" ** 64 ++ "\r\n\r\n");
        var limited = source.limited(.unlimited, &buffer);
        try testing.expectError(error.HeadTooLarge, receiveHead(&limited.interface));
    }
}

test "writeResponse" {
    var buf: [256]u8 = undefined;
    {
        var w: Io.Writer = .fixed(&buf);
        try writeResponse(&w, .{ .status = .ok, .content_type = "text/plain", .body = "ok" });
        try testing.expectEqualStrings(
            "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok",
            w.buffered(),
        );
    }
    {
        var w: Io.Writer = .fixed(&buf);
        try writeResponse(&w, .{ .status = .no_content });
        try testing.expectEqualStrings("HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n", w.buffered());
    }
}

//! `app <port>` serves the key-value API on 127.0.0.1:<port> until killed.

const std = @import("std");
const net = std.Io.net;

const Server = @import("Server.zig");
const Store = @import("Store.zig");

const listen_backlog = 1024;

pub fn main(init: std.process.Init) !void {
    const io = init.io;

    var args = init.minimal.args.iterate();
    _ = args.skip();
    const port_arg = args.next() orelse usage();
    if (args.next() != null) usage();
    const port = std.fmt.parseInt(u16, port_arg, 10) catch
        std.process.fatal("invalid port: {s}", .{port_arg});

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var listener = address.listen(io, .{
        .kernel_backlog = listen_backlog,
        .reuse_address = true,
    }) catch |err| std.process.fatal("cannot listen on 127.0.0.1:{d}: {t}", .{ port, err });
    defer listener.deinit(io);

    var store: Store = .init(init.gpa);
    defer store.deinit();

    var server: Server = .{ .io = io, .gpa = init.gpa, .store = &store };
    try server.run(&listener);
}

fn usage() noreturn {
    std.process.fatal("usage: app <port>", .{});
}

test {
    _ = @import("http.zig");
    _ = @import("router.zig");
    _ = @import("Store.zig");
    _ = Server;
}

//! Maps a request method and path to the action the server must perform.

const std = @import("std");

pub const max_key_len = 64;
const kv_prefix = "/kv/";

pub const Route = union(enum) {
    health,
    list_keys,
    get: []const u8,
    put: []const u8,
    delete: []const u8,
    /// The request is answered with a bare status code and no body.
    status: std.http.Status,
};

/// `path` is the raw request target; `key` slices in the result point into it.
pub fn resolve(method: []const u8, path: []const u8) Route {
    if (std.mem.eql(u8, path, "/health")) {
        return if (isMethod(method, "GET")) .health else .{ .status = .method_not_allowed };
    }
    if (std.mem.eql(u8, path, "/kv")) {
        return if (isMethod(method, "GET")) .list_keys else .{ .status = .method_not_allowed };
    }
    if (std.mem.startsWith(u8, path, kv_prefix)) {
        const key = path[kv_prefix.len..];
        if (!isValidKey(key)) return .{ .status = .bad_request };
        if (isMethod(method, "GET")) return .{ .get = key };
        if (isMethod(method, "PUT")) return .{ .put = key };
        if (isMethod(method, "DELETE")) return .{ .delete = key };
        return .{ .status = .method_not_allowed };
    }
    return .{ .status = .not_found };
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

/// HTTP methods are case-sensitive.
fn isMethod(method: []const u8, comptime expected: []const u8) bool {
    return std.mem.eql(u8, method, expected);
}

const testing = std.testing;

fn expectRoute(expected: Route, method: []const u8, path: []const u8) !void {
    try testing.expectEqualDeep(expected, resolve(method, path));
}

test "routes" {
    try expectRoute(.health, "GET", "/health");
    try expectRoute(.list_keys, "GET", "/kv");
    try expectRoute(.{ .get = "a" }, "GET", "/kv/a");
    try expectRoute(.{ .put = "A-z_09" }, "PUT", "/kv/A-z_09");
    try expectRoute(.{ .delete = "a" }, "DELETE", "/kv/a");
}

test "method not allowed" {
    try expectRoute(.{ .status = .method_not_allowed }, "POST", "/health");
    try expectRoute(.{ .status = .method_not_allowed }, "HEAD", "/health");
    try expectRoute(.{ .status = .method_not_allowed }, "PUT", "/kv");
    try expectRoute(.{ .status = .method_not_allowed }, "PATCH", "/kv/a");
    try expectRoute(.{ .status = .method_not_allowed }, "get", "/kv/a");
    try expectRoute(.{ .status = .method_not_allowed }, "FROB", "/kv/a");
}

test "invalid keys" {
    try expectRoute(.{ .status = .bad_request }, "GET", "/kv/");
    try expectRoute(.{ .status = .bad_request }, "GET", "/kv/bad.key");
    try expectRoute(.{ .status = .bad_request }, "PUT", "/kv/a/b");
    try expectRoute(.{ .status = .bad_request }, "GET", "/kv/a%20b");
    try expectRoute(.{ .status = .bad_request }, "PATCH", "/kv/bad.key");
    try expectRoute(.{ .status = .bad_request }, "GET", "/kv/" ++ "k" ** 65);
    try expectRoute(.{ .get = "k" ** 64 }, "GET", "/kv/" ++ "k" ** 64);
}

test "unknown paths" {
    try expectRoute(.{ .status = .not_found }, "GET", "/");
    try expectRoute(.{ .status = .not_found }, "GET", "/nope");
    try expectRoute(.{ .status = .not_found }, "GET", "/health/");
    try expectRoute(.{ .status = .not_found }, "GET", "/kvx");
    try expectRoute(.{ .status = .not_found }, "POST", "/kvs/a");
}
